pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        // Deploy a helper that reverts on receiving ether, simulating a failing callee.
        Reverter target = new Reverter();
        // Create an actor to call go() and provide them with the ether.
        address actor = makeAddr("actor");
        vm.deal(actor, amount);
        vm.prank(actor);
        // The original C's go() sends msg.value to a hardcoded address. Since we cannot modify C,
        // we instead transfer the target's address to C.owner and have the owner call go() with the
        // failing callee's address? Wait - C's go() sends to hardcoded 0xC8A60C... We cannot change
        // that. So the adversarial party must be at that address. We deploy the Reverter at that
        // exact address using vm.etch to place the code there. This is allowed because we are
        // constructing the adversarial environment.
        // Actually, Foundry lets us write code to a specific address with vm.etch.
        // We deploy Reverter first, then move its code to the hardcoded address.
        // Simpler: just deploy Reverter and then etch its runtime code to the hardcoded target.
        // But the test must be allowed to set up the adversarial counterparty at the address C expects.
        // Since C calls a hardcoded address, we must make that address the adversarial one.
        // The ADVERSARIAL COUNTERPARTY rule states: "Deploying such a helper is REQUIRED here".
        // We deploy Reverter, then use vm.etch to put its code at the hardcoded address.
        // This does not violate the rule against hardcoding "primitive deciding value" because
        // the address is a constant in C, not a fuzzed input. The fuzzed input is amount.
        bytes memory code = address(target).code;
        vm.etch(0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C, code);
        // Now call go() with the fuzzed amount.
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("go()"));
        // Assert: after the call, c's balance must be 0. This holds in reference because
        // require guarantees the transfer, and fails otherwise. Mutant skips require and
        // transfers balance after a failed call, but since the call fails, msg.value stays,
        // and the transfer sends the existing balance? Actually, go() does: payable(owner).transfer(address(this).balance)
        // So mutant transfers entire balance after failed call, meaning balance is still 0?
        // Wait, examine mutant: target.call{value: msg.value}(""); then transfer balance.
        // If call fails without require, msg.value is returned to C, so balance increases by msg.value.
        // Then transfer sends all balance to owner, so balance becomes 0 anyway.
        // But the reference reverts on failed call, so balance never increases and no transfer occurs.
        // The difference: reference reverts, mutant transfers and succeeds.
        // So after a failed call, reference reverts, mutant completes.
        // We capture the outcome of the top-level call to go().
        bool ok = success; // success is false if go() reverted
        // In reference, ok == false; in mutant, ok == true.
        // But the rule statement implies "value of state variable go differs" which is weird because go is a function.
        // Probably means "after a call to go(...) completes, the value of state variable owner?" No, the prompt says:
        // "the value of state variable `go` differs" - likely a typo for `owner` or something. But they say state variable `go`.
        // There is no state variable `go`. However, they state "assertTrue(<general fact reading c>)".
        // The general fact could be about `owner` balance or contract balance.
        // Let's derive: In C, after a successful go() (which never sends to a failing callee in normal operation, but if it does, it reverts),
        // the contract balance is 0. In mutant, after a call where callee reverts, the contract balance becomes 0 as well, so no difference.
        // So the difference must be about revert behavior. So we assert that go() always reverts when callee reverts.
        // That is a general rule: if target.call fails, go() reverts. In reference it does (require), in mutant it doesn't.
        // So we can assert that calling go() when the target reverts will cause the call to revert.
        // We can check `success` flag. `success` is false if go reverts.
        assertTrue(!ok);
        // This asserts that go() reverted. Reference passes (reverts -> success false -> ok false -> !ok true).
        // Mutant passes (does not revert -> success true -> ok true -> !ok false -> assert fails).
        // But is this a universal property? In reference, go() reverts if any target.call fails. That is not universal because it depends on input.
        // But here we have constructed an adversarial environment where the callee always reverts.
        // However, the general rule must be "for any admissible input, the correct contract obeys this rule; the buggy one violates it for some input".
        // Here admissible input includes amount. For any amount > 0, when the target reverts, reference reverts, buggy does not.
        // So we can state: "For any positive amount, when go() is called and the target address is a contract that reverts on receive, the call must revert."
        // That satisfies.
        // But we need exactly one assertion reading c's public surface. The revert boolean from try/catch is reading the outcome of c.go().
        // That is allowed.
    }
}

