// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        address target = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;
        // Ensure the target is a contract that will reject the call, simulating a failed call
        vm.etch(target, hex"fe"); // INVALID opcode causes low-level call to return false
        vm.deal(address(c), amount);
        vm.prank(address(c));
        // The reference reverts on a failed call; the mutant does not.
        // Wrap the call to detect revert.
        bool ok;
        try c.go{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }
        // After execution (or revert), the reference ensures balance is 0 if the call succeeded,
        // and if it reverted the balance is untouched (still amount).
        // The mutant, when it does not revert, leaves a non-zero balance because the transfer
        // only sends the pre-existing balance (amount) but the call value was 0, leaving the original deposit.
        // General rule: if the call did not revert, the contract's balance must be 0.
        if (ok) {
            assertEq(address(c).balance, 0, "contract balance not 0 after non-reverting go()");
        }
        // Note: The property is: (ok => balance == 0). Reference: ok => call succeeded => balance transferred => 0.
        // Mutant: ok => call failed but no revert => balance still == amount > 0 (violates).
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
